function frame(t, p, d) {
  const s = (time, t0) => spr(time, t0, 0.85, 11);

  // Animate Title
  const tOpacity = clamp(s(t, 0));
  title.style.opacity = tOpacity * 0.7;
  title.style.transform = `translateY(${lerp(10, 0, tOpacity)}px)`;

  // Animate Boxes sequentially
  boxes.forEach((el, i) => {
    const val = s(t, i * 0.8);
    const opacity = clamp(val);
    el.style.opacity = opacity;
    el.style.transform = `scale(${lerp(0.85, 1, opacity)}) translateY(${lerp(40, 0, opacity)}px)`;
  });

  // Animate Arrows between boxes
  lines.forEach((line, i) => {
    const val = s(t, i * 0.8 + 0.45);
    const progress = clamp(val);
    line.el.style.strokeDashoffset = line.len * (1 - progress);
    line.el.style.opacity = progress;
  });

  // p=.55 is 3.85s. Everything is settled by then.
}
